// @generated by:gauntlet run:complete-inventory
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::{Value, json};

fn inspect(path: &str, body: &str) -> Value {
    inspect_status(path, body, "200 OK")
}

fn inspect_status(path: &str, body: &str, status: &str) -> Value {
    let body = body.to_owned();
    let status = status.to_owned();
    let server = Server::new(move |_| response(&status, "", &body));
    let mut options = ScanOptions {
        samples: 1,
        discover: false,
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    let mut budget = limits();
    budget.max_body = 65_536;
    let report = serde_json::to_value(
        scan_configured(&format!("{}{path}", server.url), budget, &options).unwrap(),
    )
    .unwrap();
    assert_eq!(server.paths.lock().unwrap().len(), 1);
    report
}

fn find<'a>(report: &'a Value, name: &str) -> Option<&'a Value> {
    report["technologies"]
        .as_array()
        .unwrap()
        .iter()
        .find(|technology| technology["name"] == name)
}

fn technology<'a>(report: &'a Value, name: &str) -> &'a Value {
    find(report, name).unwrap_or_else(|| panic!("missing {name}: {report}"))
}

#[test]
fn unknown_composer_packages_preserve_their_locked_versions_and_ecosystem() {
    let report = inspect(
        "composer.lock",
        r#"{"packages":[{"name":"acme/internal-library","version":"v2.4.1"}],
        "packages-dev":[{"name":"acme/test-helper","version":"1.0.0"}]}"#,
    );
    let library = technology(&report, "composer:acme/internal-library");
    assert_eq!(library["kind"], "library");
    assert_eq!(library["versions"], json!(["2.4.1"]));
    assert_eq!(library["runtime_hint"], "PHP");
    assert_eq!(library["observations"][0]["method"], "composer_package");
    assert!(find(&report, "composer:acme/test-helper").is_none());
    assert!(report["version"].is_null());
}

