#[test]
fn wordpress_components_are_identified_without_promoting_cache_versions_to_exact_versions() {
    let report = inspect(
        "",
        r#"<script src='/wp-content/plugins/custom-calendar/js/main.js?ver=2.4.1&amp;private=hidden-value'></script>
        <link href='/wp-content/themes/custom-theme/style.css?ver=6.8.1'>
        <script src='/wp-includes/js/jquery/jquery.min.js?ver=3.7.1'></script>"#,
    );
    for (name, kind) in [
        ("WordPress plugin:custom-calendar", "plugin"),
        ("WordPress theme:custom-theme", "theme"),
    ] {
        let component = technology(&report, name);
        assert_eq!(component["kind"], kind);
        assert_eq!(component["versions"], json!([]));
        assert!(
            component["observations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|o| { o["method"] == "asset_path" && o["version"].is_null() })
        );
    }
    assert_eq!(technology(&report, "WordPress")["versions"], json!([]));
    assert!(!report.to_string().contains("hidden-value"));
    assert!(report["version"].is_null());
}

#[test]
fn external_and_inert_wordpress_assets_do_not_describe_target_components() {
    let report = inspect(
        "",
        r#"<script src='https://cdn.example/wp-content/plugins/external-widget/main.js'></script>
        <template><link href='/wp-content/themes/example/style.css'></template>
        <!-- <script src='/wp-content/plugins/comment-widget/main.js'></script> -->"#,
    );
    for name in [
        "WordPress plugin:external-widget",
        "WordPress theme:example",
        "WordPress plugin:comment-widget",
    ] {
        assert!(find(&report, name).is_none());
    }
}

#[test]
fn plain_phpinfo_identifies_only_allowlisted_extension_and_library_versions() {
    let report = inspect(
        "phpinfo.php",
        "phpinfo()\nPHP Version => 8.4.26\nServer API => FPM/FastCGI\nPHP API => 20240924\n\
        Redis Version => 6.1.0\nimagick module version => 3.8.0\ncURL Information => 8.10.1\n\
        OpenSSL Library Version => OpenSSL 3.0.15 3 Sep 2024\nlibXML Compiled Version => 2.12.7\n\
        Zend OPcache Version => 8.4.26\nPRIVATE_VALUE => do-not-retain-me\n",
    );
    for (name, expected) in [
        ("Redis", "6.1.0"),
        ("Imagick", "3.8.0"),
        ("cURL", "8.10.1"),
        ("OpenSSL", "3.0.15"),
        ("libxml", "2.12.7"),
        ("Zend OPcache", "8.4.26"),
    ] {
        assert_eq!(technology(&report, name)["versions"], json!([expected]));
    }
    assert!(!report.to_string().contains("do-not-retain-me"));
}

#[test]
fn html_phpinfo_keeps_extension_versions_separate_from_the_php_runtime() {
    let report = inspect(
        "phpinfo.php",
        "<h1>PHP Version 8.4.26</h1><table><tr><td>Server API</td><td>FPM/FastCGI</td></tr>\
        <tr><td>PHP API</td><td>20240924</td></tr>\
        <tr><td>Redis Version</td><td>6.1.0</td></tr>\
        <tr><td>imagick module version</td><td>3.8.0</td></tr></table>",
    );
    assert_eq!(technology(&report, "Redis")["versions"], json!(["6.1.0"]));
    assert_eq!(technology(&report, "Imagick")["versions"], json!(["3.8.0"]));
    assert_eq!(report["version"]["major"], 8);
    assert_eq!(report["version"]["minor"], 4);
    assert_eq!(report["version"]["patch"], 26);
}

