#[test]
fn section_scoped_phpinfo_versions_do_not_leak_into_unrelated_sections() {
    for body in [
        "phpinfo()\nPHP Version => 8.4.26\nServer API => FPM/FastCGI\nPHP API => 20240924\n\
        Zend OPcache\nVersion => 8.4.26\nxdebug\nVersion => 3.4.2\n\
        Unrelated Module\nVersion => 9.9.9\n",
        "<h1>PHP Version 8.4.26</h1><table><tr><td>Server API</td><td>FPM/FastCGI</td></tr>\
        <tr><td>PHP API</td><td>20240924</td></tr></table>\
        <h2>Zend OPcache</h2><table><tr><td>Version</td><td>8.4.26</td></tr></table>\
        <h2>xdebug</h2><table><tr><td>Version</td><td>3.4.2</td></tr></table>\
        <h2>Unrelated Module</h2><table><tr><td>Version</td><td>9.9.9</td></tr></table>",
    ] {
        let report = inspect("phpinfo.php", body);
        assert_eq!(
            technology(&report, "Zend OPcache")["versions"],
            json!(["8.4.26"])
        );
        assert_eq!(technology(&report, "Xdebug")["versions"], json!(["3.4.2"]));
        assert!(!report["technologies"].to_string().contains("9.9.9"));
    }
}

#[test]
fn overflowing_dependency_inventories_are_bounded_and_explicitly_truncated() {
    let packages: Vec<_> = (0..270)
        .map(|index| json!({"name":format!("acme/library-{index}"),"version":"1.2.3"}))
        .collect();
    let report = inspect("composer.lock", &json!({"packages":packages}).to_string());
    let observed = report["technologies"].as_array().unwrap();
    assert_eq!(observed.len(), 256);
    assert!(
        observed
            .iter()
            .any(|technology| technology["truncated"] == true)
    );
}

