#[test]
fn wordpress_asset_version_hints_are_separate_and_redact_unrelated_query_values() {
    let report = inspect(
        "",
        "<script src='/wp-content/plugins/custom-calendar/main.js?ver=v2.4.1&amp;private=hidden-value'></script>",
    );
    let component = technology(&report, "WordPress plugin:custom-calendar");
    let hint = component["observations"]
        .as_array()
        .unwrap()
        .iter()
        .find(|observation| observation["method"] == "asset_version_hint")
        .expect("valid asset versions should be retained as qualified hints");
    assert!(hint["version"].is_null());
    assert!(hint["detail"].as_str().unwrap().contains("2.4.1"));
    assert_eq!(component["versions"], json!([]));
    assert!(!report.to_string().contains("hidden-value"));
}

#[test]
fn duplicate_asset_version_parameters_suppress_ambiguous_hints() {
    for query in ["ver=2.4.1&amp;ver=9.9.9", "ver=2.4.1&amp;version=9.9.9"] {
        let report = inspect(
            "",
            &format!("<script src='/wp-content/plugins/custom-calendar/main.js?{query}'></script>"),
        );
        let component = technology(&report, "WordPress plugin:custom-calendar");
        assert!(
            !component["observations"]
                .as_array()
                .unwrap()
                .iter()
                .any(|observation| observation["method"] == "asset_version_hint")
        );
        assert_eq!(component["versions"], json!([]));
    }
}

#[test]
fn server_footer_versions_are_observed_only_on_errors_and_never_become_php_versions() {
    for (name, version) in [("nginx", "1.26.2"), ("Apache", "2.4.62")] {
        let body = format!("<h1>Not Found</h1><address>{name}/{version} Server</address>");
        let report = inspect_status("missing", &body, "404 Not Found");
        let server = technology(&report, name);
        assert_eq!(server["versions"], json!([version]));
        assert_eq!(server["observations"][0]["method"], "error_footer");
        assert!(report["version"].is_null());
        assert!(report["version_candidates"].as_array().unwrap().is_empty());

        let successful_page = inspect("", &body);
        assert!(find(&successful_page, name).is_none());
    }
}
